/// such fragmentation. Top-level (like [maskedValueRow]) so the settle
/// predicate is unit-testable without a PTY.
Set<String> settledJobNumbers(String raw) => shellJobSettleNotice
    .allMatches(raw)
    .map((m) => m.group(1)!.split('-').first)
