// Settled: the badge clears from the status row (the receipt stays).
await harness.waitForText(
  'done: recovered',
  timeout: const Duration(seconds: 30),
);
await harness.waitForOutput(
  settleMs: 600,
  timeout: const Duration(seconds: 20),
);
